"""Embedded voice reference audio data for Michael and Blessing."""
import zlib
import base64
import os

MICHAEL_WAV_ZLIB_B64 = ""

BLESSING_WAV_ZLIB_B64 = ""

def unpack_embedded_voice(voice_name: str, target_dir: str) -> str:
    """
    Auto-extract embedded reference voice audio WAV file to target_dir if missing on server.
    Ensures zero-shot XTTS voice conditioning always has authentic audio reference on disk.
    """
    v_clean = str(voice_name or "michael").lower().strip()
    is_michael = ("m" in v_clean or "male" in v_clean)
    target_file = "michael.wav" if is_michael else "blessing.wav"
    b64_data = MICHAEL_WAV_ZLIB_B64 if is_michael else BLESSING_WAV_ZLIB_B64

    target_path = os.path.join(target_dir, target_file)
    if not os.path.exists(target_path) or os.path.getsize(target_path) < 1000:
        try:
            os.makedirs(target_dir, exist_ok=True)
            raw = zlib.decompress(base64.b64decode(b64_data))
            with open(target_path, "wb") as f:
                f.write(raw)
            print(f"[EmbeddedVoices] Unpacked authentic {target_file} ({len(raw)} bytes) -> {target_path}")
        except Exception as e:
            print(f"[EmbeddedVoices] Failed to unpack {target_file}: {e}")
    return target_path
